function initGL(){const vs=`attribute vec3 position;attribute vec3 normal;attribute vec3 color;uniform mat4 matrix;varying vec3 vColor;varying vec3 vNormal;varying float vDepth;void main(){gl_Position=matrix*vec4(position,1.);vColor=color;vNormal=normal;vDepth=position.y;}`;
const fs=`precision mediump float;varying vec3 vColor;varying vec3 vNormal;varying float vDepth;uniform float dusk;void main(){vec3 light=normalize(vec3(-.6,1.,.8));float diffuse=max(dot(normalize(vNormal),light),0.);vec3 c=vColor*(.68+diffuse*.33);vec3 warm=c*vec3(1.05,.89,.78);c=mix(c,warm,dusk*.67);gl_FragColor=vec4(c,1.);}`;
function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));gl.useProgram(program);geometry();const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.STATIC_DRAW);count=vertices.length/9;for(const[name,offset]of[['position',0],['normal',3],['color',6]]){let loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,3,gl.FLOAT,false,36,offset*4);}uMatrix=gl.getUniformLocation(program,'matrix');uDusk=gl.getUniformLocation(program,'dusk');gl.enable(gl.DEPTH_TEST);gl.enable(gl.CULL_FACE);gl.cullFace(gl.BACK);}
const markers=data.spots.map(s=>{const b=document.createElement('button');b.className='spot';b.innerHTML=`<b>${s.number}</b>${s.title}<span class="arrow">↗</span>`;b.setAttribute('aria-label',`${s.subtitle}：${s.title}`);b.onclick=()=>openSpot(s.id);$('#labels').append(b);return{el:b,spot:s,building:data.buildings.find(x=>x.id===s.id)};});
function camera(){const aspect=innerWidth/innerHeight,span=(isRoom?(innerWidth<760?2.8/aspect:2.8):(innerWidth<760?23/aspect:24))/zoom;const shift=innerWidth>760&&!selected?[isRoom?-.35:-2,0,0]:[0,0,0];const at=target.map((v,i)=>v+shift[i]);const r=60,eye=[at[0]+Math.sin(yaw)*Math.cos(pitch)*r,at[1]+Math.sin(pitch)*r,at[2]+Math.cos(yaw)*Math.cos(pitch)*r];viewProjection=multiply(ortho(-span*aspect,span*aspect,-span,span,.1,180),lookAt(eye,at));}
