function draw(){frame=requestAnimationFrame(draw);const ease=reduced?1:.075;yaw+=(desiredYaw-yaw)*ease;zoom+=(desiredZoom-zoom)*ease;target=target.map((v,i)=>v+(desiredTarget[i]-v)*ease);camera();if(gl){const bg=dusk?[.36,.385,.4]:[.925,.922,.898];gl.clearColor(...bg,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.uniformMatrix4fv(uMatrix,false,viewProjection);gl.uniform1f(uDusk,dusk?1:0);gl.drawArrays(gl.TRIANGLES,0,count);}for(const m of markers){const b=m.building,p=project([b.x,b.h+(isRoom?.14:1),b.z]);m.el.style.left=p[0]+'px';m.el.style.top=p[1]+'px';m.el.style.visibility=p[0]<20||p[0]>innerWidth-20||p[1]<90||p[1]>innerHeight-80?'hidden':'visible';m.el.setAttribute('aria-pressed',selected===m.spot.id?'true':'false');}$('#needle').style.transform=`rotate(${-yaw*180/Math.PI}deg)`;}
function focusBuilding(b){desiredTarget=[b.x-(innerWidth>760?(isRoom?.9:4):0),isRoom?b.h:b.h*.35,b.z];desiredZoom=innerWidth<760?(isRoom?1.15:1.05):(isRoom?1.8:1.45);}
function openSpot(id){const s=data.spots.find(s=>s.id===id);selected=id;previousFocus=document.activeElement;focusBuilding(data.buildings.find(b=>b.id===id));$('#panel-kicker').textContent=`SPOT ${s.number} — ${s.subtitle}`;$('#panel-title').textContent=s.title;$('#panel-copy').textContent=s.copy;$('#shelf').replaceChildren();s.books.forEach((book,i)=>{const b=document.createElement('button');b.className='book';b.style.setProperty('--book',book.color);b.innerHTML=`<small>VOL. 0${i+1}</small><span>${book.title}</span><em>0${i+1}</em>`;b.onclick=()=>openBook(s,book,i);$('#shelf').append(b);});$('#panel').hidden=false;document.body.classList.add('panel-open');$('#close-panel').focus({preventScroll:true});}
function closePanel(){selected=null;$('#panel').hidden=true;document.body.classList.remove('panel-open');desiredTarget=[0,1,0];desiredZoom=1;if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
function openBook(spot,book,i){$('#detail-content').innerHTML=`<div class="project-art" style="--art:${book.color}" aria-hidden="true"></div><span class="sample-label">${spot.id==='trash'?'ARCHIVED / ボツ案':spot.id==='books'?'OSS / CODE':(spot.id==='51'&&i!==1)||spot.id==='pc'||(spot.id==='note'&&i===0)?'PERSONAL NOTE':'サンプル展示 / 実績ではありません'}</span><h2>${book.title}</h2><div class="project-meta"><span>${book.type}</span><span>${spot.subtitle} / VOL. 0${i+1}</span></div><p>${book.copy}</p><p>この展示は、実際の作品・写真・リンクに差し替えられるプロトタイプです。</p>`;$('#details').showModal();}
$('#close-panel').onclick=closePanel;$('#reset').onclick=()=>{closePanel();desiredYaw=homeYaw;pitch=homePitch;};$('#zoom-in').onclick=()=>desiredZoom=Math.min(2.4,desiredZoom*1.16);$('#zoom-out').onclick=()=>desiredZoom=Math.max(.65,desiredZoom/1.16);$('#day').onclick=()=>{dusk=!dusk;document.body.classList.toggle('dusk',dusk);$('#day').textContent=dusk?'☾':'☀';$('#day').setAttribute('aria-label',dusk?'昼に切り替え':'夕方に切り替え');};$('#tour').onclick=()=>openSpot(data.spots[0].id);
$('#about').onclick=()=>{$('#detail-content').innerHTML='<div class="eyebrow">ABOUT THIS LITTLE WORLD</div><h2>ここから、僕の世界へ。</h2><p>早稲田大学に通う学生の、個人サイトのプロトタイプです。日常の場所を入口に、制作物や自分のことを知ってもらえる体験を考えています。</p>'+(isRoom?'<p>写真一枚をもとに、窓辺の机、ベッド、黒い椅子、手前のテーブル、足元の緑のゴミ箱を小さな3Dの部屋にしました。寸法や、写真に写っていない部分は推定です。</p><p>本をクリックすると自作OSS、緑のゴミ箱をクリックするとアーカイブやボツ案、机のPCからはWebアプリの記録が開きます。</p>':'<p>早稲田大学の公式サイトではありません。公式案内を参考にした簡略模型で、配置・縮尺・外観は実測に基づかない表現です。展示内容の一部はサンプルです。</p><p><a href="https://www.waseda.jp/top/access/nishiwaseda-campus" target="_blank" rel="noopener noreferrer">参考：早稲田大学 西早稲田キャンパス案内 ↗</a></p>')+'<p>ドラッグで回転、ホイールやピンチで拡大できます。上の切り替えから、部屋とキャンパスを行き来できます。</p>';$('#details').showModal();};
for(const[id,dialog]of[['close-details','details'],['close-locations','location-dialog']])$('#'+id).onclick=()=>$('#'+dialog).close();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
for(const s of data.spots){let b=document.createElement('button');b.className='location-row';b.innerHTML=`<b>${s.number}</b><span>${s.title}<small>${s.subtitle}</small></span>↗`;b.onclick=()=>{$('#location-dialog').close();openSpot(s.id);};$('#location-list').append(b);}$('#locations').onclick=()=>$('#location-dialog').showModal();
