const touches=new Map();let lastPinch=0;
canvas.addEventListener('pointerdown',e=>{touches.set(e.pointerId,[e.clientX,e.clientY]);canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,yaw:desiredYaw,pitch};didDrag=false;lastPinch=0;});
canvas.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,[e.clientX,e.clientY]);if(touches.size===2){const p=[...touches.values()],d=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);if(lastPinch)desiredZoom=Math.max(.65,Math.min(2.4,desiredZoom*d/lastPinch));lastPinch=d;didDrag=true;return;}if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5)didDrag=true;desiredYaw=isRoom?Math.max(-1.05,Math.min(1.2,drag.yaw-dx*.006)):drag.yaw-dx*.006;pitch=Math.max(.35,Math.min(1.18,drag.pitch+dy*.003));});
function pickBuilding(x,y){if(isRoom){let nearest=null,distance=Infinity;for(const m of markers){const b=m.building,p=project([b.x,b.h-.06,b.z]),d=Math.hypot(x-p[0],y-p[1]);if(d<Math.min(65,38*zoom)&&d<distance){nearest=m.spot.id;distance=d;}}if(nearest)openSpot(nearest);return;}let best=null,bestDistance=Infinity;for(const m of markers){const b=m.building,base=project([b.x,0,b.z]),top=project([b.x,b.h,b.z]);const dx=x-top[0],cy=Math.max(Math.min(y,base[1]),top[1]);const distance=Math.hypot(dx,y-cy);if(distance<bestDistance&&distance<55*zoom){best=m.spot.id;bestDistance=distance;}}if(best)openSpot(best);}
